public class LeapYearFinder {

    /**
     * Finds the Nth leap year after the start year Y.
     *
     * @param Y The start year.
     * @param N The position of the leap year to find.
     * @return The Nth leap year after the start year Y if it exists, otherwise -1.
     */
    public static int findNthLeapYear(int Y, int N) {
        if (N < 0) return -1;

        int count = 0;
        while (count < N) {
            if (isLeapYear(Y)) {
                count++;
            }
            if (count < N) {
                Y++;
            }
        }
        return Y;
    }

    /**
     * Checks if the given year is a leap year.
     *
     * @param year the year to check
     * @return true if the year is a leap year, false otherwise
     */
    private static boolean isLeapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }
}
