public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    Set<String> substrings = new HashSet<>();
    for (String str : strings) {
        for (int i = 0; i < str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                substrings.add(str.substring(i, j));
            }
        }
    }

    Set<String> inverseSubstrings = new HashSet<>();
    for (String sub : substrings) {
        inverseSubstrings.add(new StringBuilder(sub).reverse().toString());
    }

    for (int length = Math.max(0, substrings.size() - 1); length >= 0; length--) {
        for (String sub : substrings) {
            if (sub.length() == length) {
                for (String str : strings) {
                    if (str.contains(sub) || str.contains(sub)) {
                        return length;
                    }
                }
            }
        }
    }

    return 0;
}
