    }

    int maxSize = 0;

    for (String str : strings) {
        for (String reverseStr : strings) {
            if (str.equals(reverseStr)) {
                continue;
            }
            if (str.contains(reverseStr) || reverseStr.contains(str)) {
                maxSize = Math.max(maxSize, Math.min(str.length(), reverseStr.length()));
            }
        }
    }

    return maxSize;
}
