public static int maxRegions(int N) {
    // Base case: with 0 triangles, there's 1 region (the whole plane)
    if (N == 0) {
        return 1;
    }

    // Initialize the number of regions
    int regions = 1;

    // For each additional triangle, it can intersect with all existing regions
    for (int i = 1; i <= N; i++) {
        regions += i * 2;
    }

    return regions;
}
