public class PrefixCounter {

    /**
     * Counts the number of words in the given word list that have the given prefix.
     * 
     * @param wordList the list of words
     * @param prefix   the prefix string
     * @return the number of words with the given prefix
     */
    public static int countPrefixWords(List<String> wordList, String prefix) {
        int count = 0;
        for (String word : wordList) {
            if (word.startsWith(prefix)) {
                count++;
            }
        }
        return count;
    }

    // Test cases to verify the solution
    public static void main(String[] args) {
        System.out.println(countPrefixWords(Arrays.asList("banana", "band", "bee", "absolute", "acm"), "ba")); // Expected output: 2
        System.out.println(countPrefixWords(Arrays.asList("banana", "band", "bee", "absolute", "acm"), "b")); // Expected output: 3
        System.out.println(countPrefixWords(Arrays.asList("banana", "band", "bee", "absolute", "acm"), "band")); // Expected output: 1
    }
}
