public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] graph = new boolean[n][n];
    for (int[] path : paths) {
        graph[path[0]][path[1]] = true;
        graph[path[1]][path[0]] = true;
    }
    boolean[] visited = new boolean[n];
    boolean result = dfs(graph, n, start[0], end[0], visited);
    if (result) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(boolean[][] graph, int n, int current, int end, boolean[] visited) {
    visited[current] = true;
    if (current == end) {
        return true;
    }
    for (int i = 0; i < n; i++) {
        if (graph[current][i] && !visited[i]) {
            if (dfs(graph, n, i, end, visited)) {
                return true;
            }
        }
    }
    visited[current] = false;
    return false;
}
