public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n * n];
    return dfs(start, end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int[] current, int[] end, int[][] paths, boolean[] visited) {
    int currentIndex = current[0] * n + current[1];
    if (currentIndex == end[0] * n + end[1]) {
        return true;
    }
    if (visited[currentIndex]) {
        return false;
    }
    visited[currentIndex] = true;
    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        if ((path[0] == currentIndex || path[1] == currentIndex) && !visited[path[path[0] == currentIndex ? 1 : 0]]) {
            if (dfs(new int[]{path[path[0] == currentIndex ? 1 : 0] / n, path[path[0] == currentIndex ? 1 : 0] % n}, end, paths, visited)) {
                return true;
            }
        }
    }
    visited[currentIndex] = false;
    return false;
}
