public class ApproximateValueCalculator {

    /**
     * Calculates the approximate value by counting the number of common letters
     * and dividing it by the sum of the lengths of the two words.
     *
     * @param word1 The first word.
     * @param word2 The second word.
     * @return The approximate value as a reduced fraction.
     */
    public static String appx(String word1, String word2) {
        Set<Character> set1 = new HashSet<>();
        Set<Character> set2 = new HashSet<>();

        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        set1.retainAll(set2);
        int commonLetters = set1.size();
        int totalLength = word1.length() + word2.length();

        return "appx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + totalLength;
    }

    public static void main(String[] args) {
        System.out.println(appx("CAR", "CART")); // Output: appx(CAR, CART) = 6/7
        System.out.println(appx("TURKEY", "CHICKEN")); // Output: appx(TURKEY, CHICKEN) = 4/13
        System.out.println(appx("MONEY", "POVERTY")); // Output: appx(MONEY, POVERTY) = 1/3
        System.out.println(appx("ROUGH", "PESKY")); // Output: appx(ROUGH, PESKY) = 0
        System.out.println(appx("A", "A")); // Output: appx(A, A) = 1
    }
}
