                visited1[i] = true;
                visited2[j] = true;
                break;
            }
        }
    }

    int sumOfLengths = len1 + len2;
    int gcd = gcd(commonLetters, sumOfLengths);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters / gcd) + "/" + (sumOfLengths / gcd);
