import java.util.HashMap;
import java.util.Map;

public class CanArrangePairs {

    public boolean canArrange(int[] arr, int k) {
        if (arr.length % 2 != 0) {
            return false;
        }

        Map<Integer, Integer> remainderCount = new HashMap<>();

        for (int num : arr) {
            int remainder = (num % k + k) % k; // Ensure positive remainder
            remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
        }

        for (int remainder : remainderCount.keySet()) {
            if (remainder == 0) {
                // Pairs with remainder 0 must have even counts
                if (remainderCount.get(remainder) % 2 != 0) {
                    return false;
                }
            } else {
                int complement = (k - remainder) % k;
                if (!remainderCount.containsKey(complement) || remainderCount.get(remainder) != remainderCount.get(complement)) {
                    return false;
                }
            }
        }

        return true;
    }

    public static void main(String[] args) {
        CanArrangePairs test = new CanArrangePairs();
        // Test case 1: True, possible to divide into pairs with sum divisible by 5
        int[] arr1 = {1, 2, 3, 4, 5, 10, 6, 7, 8, 9};
        System.out.println(test.canArrange(arr1, 5)); // Output: true

        // Test case 2: True, possible to divide into pairs with sum divisible by 7
        int[] arr2 = {1, 2, 3, 4, 5, 6};
        System.out.println(test.canArrange(arr2, 7)); // Output: true

        // Test case 3: False, not possible to divide into pairs with sum divisible by 10
        int[] arr3 = {1, 2, 3, 4, 5, 6};
        System.out.println(test.canArrange(arr3, 10)); // Output: false
    }
}
