class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        LinkedList<Integer>[] graph = new LinkedList[n];
        for (int i = 0; i < n; ++i) {
            graph[i] = new LinkedList<>();
        }
        boolean[] visited = new boolean[n];
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        return helper(0, graph, hasApple, visited);
    }

    private int helper(int i, LinkedList<Integer>[] graph, boolean[] hasApple, boolean[] visited) {
        int totalTime = 0;
        visited[i] = true;
        for (int j : graph[i]) {
            if (visited[j]) continue;
            int time = helper(j, graph, hasApple, visited);
            if (time > 0 || hasApple[j]) {
                totalTime += time + 2;
            }
        }
        return totalTime;
    }
}
