import java.util.*;

public class Solution {
    public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length;
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }

        if (n == 1) {
            return false;
        }

        Set<Double> setAverages = new HashSet<>();
        setAverages.add(0.0);
        setAverages.add((double) sum / n);

        for (int i = 1; i <= (n / 2); i++) {
            setAverages = generateAverages(nums, i, setAverages);
            if (setAverages.contains((double) sum / (n - i))) {
                return true;
            }
        }

        return false;
    }

    private Set<Double> generateAverages(int[] nums, int length, Set<Double> averages) {
        Set<Double> newAverages = new HashSet<>();
        for (int num : nums) {
            for (double avg : averages) {
                newAverages.add(avg + (double) num / length);
            }
        }
        return newAverages;
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        System.out.println(sol.splitArraySameAverage(new int[]{1, 2, 3, 4, 5, 6, 7, 8})); // true
        System.out.println(sol.splitArraySameAverage(new int[]{3, 1})); // false
    }
}
