public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    Set<Double>[] dp = new HashSet[n / 2 + 1];
    for (int i = 0; i <= n / 2; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0.0);

    for (int num : nums) {
        for (int i = n / 2; i > 0; i--) {
            for (double sum : dp[i - 1]) {
                dp[i].add(sum + num);
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (double sum : dp[i]) {
            if (sum * n == totalSum * i) return true;
        }
    }

    return false;
}
