public class BinarySubstringChecker {

    /**
     * Check if every binary string of length k is a substring of the given string s.
     *
     * @param s the binary string to check
     * @param k the length of the binary strings to check for
     * @return true if every binary string of length k is a substring of s, false otherwise
     */
    public static boolean hasAllCodes(String s, int k) {
        if (s.length() < (Math.pow(2, k) + k - 1)) {
            return false;
        }

        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            seen.add(s.substring(i, i + k));
        }

        return seen.size() == Math.pow(2, k);
    }

    public static void main(String[] args) {
