    public static boolean hasAllCodes(String s, int k) {
        Set<String> set = new HashSet<>();
        int n = s.length();

        // Check if the length of the string is sufficient to contain all binary strings of length k
        if (n < Math.pow(2, k)) {
            return false;
        }

        // Iterate through the string and add all substrings of length k to the set
        for (int i = 0; i <= n - k; i++) {
            set.add(s.substring(i, i + k));
        }

        // Check if the number of unique substrings is equal to 2^k
        return set.size() == Math.pow(2, k);
