public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int answer = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (close % 2 != 0) {
                answer++;
                close--;
            }
            open++;
        } else {
            close++;
            if (close == 2) {
                open--;
                close = 0;
            }
            if (open == 0 && i < s.length() - 1 && s.charAt(i + 1) == ')') {
                answer++;
                i++;
            }
        }
    }

    return answer + open * 2 + close * 2;
}
