public class Solution {
    public int minInsertions(String s) {
        int balance = 0;
        int insertions = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                if ((i + 1 < s.length() && s.charAt(i + 1) == ')')) {
                    i++; // Skip the next character as it's a valid pair
                } else {
                    insertions++; // Need an extra ')' to balance this '('
                }
                balance++;
            } else { // s.charAt(i) == ')'
                if (balance == 0) {
                    insertions++; // Need an extra '(' to balance this ')'
                } else {
                    balance--;
                }
            }
        }

        return insertions + balance * 2; // Total insertions needed
    }

    public static void main(String[] args) {
        Solution solution = new Solution();

        // Test cases
        System.out.println(solution.minInsertions("(()))")); // Expected output: 1
        System.out.println(solution.minInsertions("((()))")); // Expected output: 0
    }
}
