public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int temp = a + b;
        a = b;
        b = temp;
    }

    int count = 0;
    while (k > 0) {
        int index = fibs.size() - 1;
        while (index >= 0 && fibs.get(index) > k) {
            index--;
        }
        k -= fibs.get(index);
        count++;
    }

    return count;
}

