    // Generate Fibonacci numbers <= k
    while (true) {
        int nextFib = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
        if (nextFib > k) {
            break;
        }
        fibNumbers.add(nextFib);
    }

    int count = 0;
    int index = fibNumbers.size() - 1;

    // Find the minimum number of Fibonacci numbers whose sum is equal to k
    while (k > 0) {
        if (fibNumbers.get(index) <= k) {
            k -= fibNumbers.get(index);
            count++;
        }
        index--;
    }

    return count;
}
