public class KthFactorFinder {

    /**
     * Finds the k-th factor of a given number n.
     * A factor of n is a positive integer that divides n evenly.
     * Returns the k-th factor in ascending order. If n has less than k factors, returns -1.
     *
     * @param n the number to find the factor for
     * @param k the order of the factor to find
     * @return the k-th factor of n, or -1 if n has less than k factors
     */
    public int kthFactor(int n, int k) {
        int count = 0;

        for (int i = 1; i <= n; i++) {
            if (n % i == 0) {
                count++;
                if (count == k) {
                    return i;
                }
            }
        }

        return -1;
    }

    public static void main(String[] args) {
        KthFactorFinder finder = new KthFactorFinder();

        System.out.println(finder.kthFactor(12, 3)); // Expected output: 3
        System.out.println(finder.kthFactor(7, 2));  // Expected output: 7
        System.out.println(finder.kthFactor(4, 4));  // Expected output: -1
    }
