    for (char c : s.toCharArray()) {
        if (stack.isEmpty()) {
            stack.append(c);
        } else {
            char last = stack.charAt(stack.length() - 1);
            if (Character.isLetter(last) && Character.isLetter(c) && Math.abs(last - c) == 32) {
                stack.deleteCharAt(stack.length() - 1);
            } else {
                stack.append(c);
            }
        }
    }
    return stack.toString();
}
