     * one is a lowercase letter and the other is the corresponding uppercase letter.
     *
     * @param s the input string consisting of lowercase and uppercase English letters
     * @return the final "good" string
     */
    public static String makeGood(String s) {
        // Use a StringBuilder to efficiently build the result string
        StringBuilder result = new StringBuilder();
        boolean valid = true;

        while (valid) {
            valid = false;
            int prevIndex = -1;
            for (int i = 0; i < result.length(); i++) {
                if (i > prevIndex && Math.abs(result.charAt(prevIndex) - result.charAt(i)) == 32) {
                    // Found adjacent characters that are opposite cases
                    prevIndex--;
                    valid = true;
                } else {
                    result.setCharAt(prevIndex + 1, result.charAt(i));
                    prevIndex++;
                }
            }
            if (prevIndex < result.length() - 1) {
                result.setLength(prevIndex + 1);
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(makeGood("leEeetcode")); // Output: "leetcode"
        System.out.println(makeGood("abBAcC"));     // Output: ""
        System.out.println(makeGood("s"));          // Output: "s"
    }
}
