public int maxUniqueSplit(String s) {
    HashSet<String> set = new HashSet<>();
    return split(s, 0, set);
}

private int split(String s, int start, HashSet<String> set) {
    if (start == s.length()) {
        return set.size();
    }

    int maxUnique = 0;
    for (int i = start; i < s.length(); i++) {
        String substring = s.substring(start, i + 1);
        if (!set.contains(substring)) {
            set.add(substring);
            maxUnique = Math.max(maxUnique, split(s, i + 1, set));
            set.remove(substring);
        }
    }

    return maxUnique;
}

