private int maxUniqueSplitHelper(String s, Set<String> uniqueSubstrings) {
    if (s.isEmpty()) {
        return uniqueSubstrings.size();
    }

    int maxUniqueCount = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (uniqueSubstrings.add(prefix)) {
            maxUniqueCount = Math.max(maxUniqueCount, maxUniqueSplitHelper(s.substring(i), uniqueSubstrings));
            uniqueSubstrings.remove(prefix);
        }
    }

    return maxUniqueCount;
