public class SumOfDigits {
    /**
     * Repeatedly adds all the digits of a non-negative integer until the result is a single digit.
     *
     * @param num The non-negative integer to perform the operation on.
     * @return The single digit result after repeatedly adding all digits.
     */
    public static int addDigits(int num) {
        while (num >= 10) {
            int sum = 0;
            while (num > 0) {
                sum += num % 10;
                num /= 10;
            }
            num = sum;
        }
        return num;
    }

    public static void main(String[] args) {
        // Test cases to verify the solution
        System.out.println(addDigits(38)); // Output: 2
        System.out.println(addDigits(0));  // Output: 0
        System.out.println(addDigits(123)); // Output: 6
    }
}
