    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // Arrays to store the lengths of continuous 1s in each direction
    int[][][] dp = new int[m + 1][n + 1][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                dp[i + 1][j + 1][0] = dp[i + 1][j][0] + 1;
                // Vertical
                dp[i + 1][j + 1][1] = dp[i][j + 1][1] + 1;
                // Diagonal
                dp[i + 1][j + 1][2] = dp[i][j][2] + 1;
                // Anti-diagonal
                dp[i + 1][j + 1][3] = dp[i][j + 2][3] + 1;

                // Update the longest line length
                longest = Math.max(longest, Math.max(dp[i + 1][j + 1][0], dp[i + 1][j + 1][1]));
                longest = Math.max(longest, Math.max(dp[i + 1][j + 1][2], dp[i + 1][j + 1][3]));
            }
        }
    }

    return longest;
}
