public static int squarePermutations(int[] A) {
    int N = A.length;
    if (N <= 1) {
        return 1;
    }

    boolean[] used = new boolean[N];
    return backtrack(A, -1, used, 0);
}

private static boolean isPerfectSquare(int x) {
    int sqrt = (int) Math.sqrt(x);
    return sqrt * sqrt == x;
}

private static int backtrack(int[] A, int prev, boolean[] used, int index) {
    if (index == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i] && (prev == -1 || isPerfectSquare(prev + A[i]))) {
            used[i] = true;
            count += backtrack(A, A[i], used, index + 1);
            used[i] = false;
        }
    }

    return count;
}
