public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return 0;
    }

    int N = A.length;
    boolean[] visited = new boolean[N];
    int count = 0;

    for (int i = 0; i < N; i++) {
        if (!visited[i]) {
            count += backtrack(A, visited, i, N);
        }
    }

    return count;
}

private static int backtrack(int[] A, boolean[] visited, int start, int N) {
    int count = 0;
    visited[start] = true;

    if (start == N - 1) {
        return 1;
    }

    for (int i = start + 1; i < N; i++) {
        if (!visited[i] && isPerfectSquare(A[start] + A[i])) {
            count += backtrack(A, visited, i, N);
        }
    }

    visited[start] = false;
    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}
