private static int countPermutations(int[] A, int index, boolean[] used) {
    if (index == A.length - 1) return 1;

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (index == 0 || (int) Math.sqrt(A[index] + A[i]) * (int) Math.sqrt(A[index] + A[i]) == A[index] + A[i]) {
                used[i] = true;
                count += countPermutations(A, index + 1, used);
                used[i] = false;
            }
        }
    }

    return count;
