import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }
        return backtrack(A, 0, new boolean[A.length]);
    }

    private static int backtrack(int[] A, int start, boolean[] used) {
        if (start == A.length) {
            return 1;
        }
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (used[i] || (start > 0 && !isPerfectSquare(A[start - 1] + A[i]))) {
                continue;
            }
            used[i] = true;
            count += backtrack(A, start + 1, used);
            used[i] = false;
        }
        return count;
    }

    private static boolean isPerfectSquare(int n) {
        int sqrt = (int) Math.sqrt(n);
        return sqrt * sqrt == n;
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
}
