    for (int k = 0; k < rows + cols - 1; k++) {
        if (k % 2 == 0) {
            for (int i = Math.min(k, rows - 1); i >= 0; i--) {
                result[index++] = mat[i][k - i];
            }
        } else {
            for (int i = Math.min(k, cols - 1); i >= 0; i--) {
                result[index++] = mat[k - i][i];
            }
        }
    }

    return result;
}
