public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, di = 1;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        r += di;
        c -= di;

        if (r >= rows) {
            r = rows - 1;
            c += 2;
            di = -di;
        } else if (c >= cols) {
            c = cols - 1;
            r += 2;
            di = -di;
        } else if (r < 0) {
            r = 0;
            di = -di;
        } else if (c < 0) {
            c = 0;
            di = -di;
        }
    }

    return result;
}
