public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first decreasing digit from the right
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to rearrange to be greater)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) but greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i) position in ascending order
    Arrays.sort(digits, i + 1, length);

    // Convert the char array back to an integer
    return Integer.parseInt(new String(digits));
}
