import java.util.Arrays;

public class SmallestIntegerFinder {

    /**
     * Finds the smallest integer greater than n by rearranging its digits.
     *
     * @param n The input positive integer.
     * @return The smallest rearranged integer greater than n, or -1 if not possible.
     */
    public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();

        // Start from the right, find the first digit that is smaller than the digit next to it
        int i;
        for (i = digits.length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                break;
            }
        }

        // If no such digit is found, return -1
        if (i == -1) {
            return -1;
        }

        // Find the smallest digit to the right of i that is greater than digits[i]
        int j;
        for (j = digits.length - 1; j > i; j--) {
            if (digits[j] > digits[i]) {
                break;
            }
        }

        // Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Sort the digits to the right of i in ascending order
        Arrays.sort(digits, i + 1, digits.length);

        // Convert the digits back to an integer
        return Integer.parseInt(new String(digits));
    }
}
