import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        if (n <= 0) {
            return new ArrayList<>();
        }
        if (n == 1) {
            return new ArrayList<>(List.of("0", "1", "8"));
        }

        List<String> result = new ArrayList<>();
        if (n % 2 == 0) {
            backtrack(result, new char[n], 0, n - 1);
        } else {
            backtrack(result, new char[n], 0, n - 2);
            result.addAll(addMiddle(result, '0'));
            result.addAll(addMiddle(result, '1'));
            result.addAll(addMiddle(result, '8'));
        }

        return result;
    }

    private static void backtrack(List<String> result, char[] path, int left, int right) {
        if (left > right) {
            result.add(new String(path));
            return;
        }

        if (left == right) {
            path[left] = '0';
            result.add(new String(path));
            path[left] = '1';
            result.add(new String(path));
            path[left] = '8';
            return;
        }

        if (left < right) {
            path[left] = '0';
            path[right] = '0';
            backtrack(result, path, left + 1, right - 1);

            path[left] = '6';
            path[right] = '9';
            backtrack(result, path, left + 1, right - 1);

            path[left] = '8';
            path[right] = '8';
            backtrack(result, path, left + 1, right - 1);

            path[left] = '9';
            path[right] = '6';
            backtrack(result, path, left + 1, right - 1);
        }
    }

    private static List<String> addMiddle(List<String> list, char middle) {
        List<String> result = new ArrayList<>();
        for (String num : list) {
            result.add(num.substring(0, num.length() / 2) + middle + num.substring(num.length() / 2));
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: ["11","69","88","96"]
        System.out.println(centerSymmetricNumbers(1)); // Output: ["0","1","8"]
    }
}
